def isolated_integers(W1, W2, limit=40):
    # S = {a*W1 + b*W2 : a,b in {-1,0,1}}
    S = sorted({a*W1 + b*W2 for a in (-1,0,1) for b in (-1,0,1)})
    # positive part
    P = [s for s in S if s > 0]
    # integers m>=1 are isolated iff m in P, or m is the unique integer in a bounded interval between consecutive S values (including (0,p1))
    # bounded intervals: (0,p1),(p1,p2),...,(p_{k-1},p_k)
    bounds = [Fraction(0)] + P
    iso = set()
    for i in range(len(bounds)-1):
        lo, hi = bounds[i], bounds[i+1]
        # integers strictly inside
        ints = [m for m in range(1, limit+1) if lo < m < hi]
        if len(ints) == 1:
            iso.add(ints[0])
    for p in P:
        if p.denominator == 1 and p >= 1:
            iso.add(int(p))
    return iso

