def pieces_from_cuts(n, cuts):
    # cuts: set of ring indices (0-based) that are cut open -> loose rings
    # segments are runs of uncut rings between cut rings
    cutset = set(cuts)
    loose = len(cutset)
    segs = []
    run = 0
    for i in range(n):
